    private void respond(JavaScriptReplyProxy reply,String id,JSONObject value,String error){runOnUiThread(()->{if(destroyed)return;try{JSONObject result=new JSONObject().put("id",id);if(error!=null)result.put("error",error);else result.put("value",value==null?new JSONObject():value);reply.postMessage(result.toString());}catch(Exception ignored){}});}
    private static String cleanError(Throwable e){Throwable cause=e instanceof ExecutionException&&e.getCause()!=null?e.getCause():e;return cause.getMessage()==null?cause.getClass().getSimpleName():cause.getMessage();}
    void show(String name){runOnUiThread(()->safe(()->{if(!name.equals("home")&&!name.equals("chat")&&!name.equals("game"))return;if(name.equals("chat")&&!packs.hasChat()){notice("请先导入随本版提供的 Fritia-Chat-Mobile-v4.qchat。");pickImport();return;}if(conversation.busy()&&!name.equals(surface)){notice("请先停止或等待当前回复。");return;}speech.stop();network.cancelAll();String previous=surface;surface=name;if(previous.equals("home"))clearTouches();if(previous.equals("home"))script("home","window.QibanHome?.suspend()");if(previous.equals("game"))script("game","window.QibanCards?.suspend()");if(previous.equals("chat"))script("chat","window.QibanAndroid?.suspend();window.QibanNative?.stopAllSpeech()");for(WebView v:views.values())v.setVisibility(View.GONE);WebView next=views.get(name);if(next==null){next=create(name);views.put(name,next);content.addView(next,new FrameLayout.LayoutParams(-1,-1));}else if(name.equals("chat")&&!previous.equals("chat"))next.reload();next.setVisibility(View.VISIBLE);next.onResume();toolbar.setVisibility(name.equals("chat")?View.VISIBLE:View.GONE);toolbar.surface(name);setSurfaceChrome(name);setRequestedOrientation(name.equals("game")?ActivityInfo.SCREEN_ORIENTATION_SENSOR_LANDSCAPE:ActivityInfo.SCREEN_ORIENTATION_UNSPECIFIED);if(name.equals("home")){script(name,"window.QibanHome?.resume()");sensors.resume();}else sensors.pause();if(name.equals("game"))script(name,"window.QibanCards?.resume()");}));}
